type clock time.Time

func (c clock) Now() time.Time { return time.Time(c) }

// Wednesday 2026-03-11, mid-afternoon UTC.
var now = clock(time.Date(2026, 3, 11, 15, 30, 0, 0, time.UTC))

func date(s string) time.Time {
	d, err := time.Parse(time.DateOnly, s)
	if err != nil {
		panic(err)
	}
	return d
}

// T1: core.

func TestCoreDayIsTheUTCDate(t *testing.T) {
	east := time.FixedZone("east", 5*3600)
	for _, c := range []struct {
		in   time.Time
		want string
	}{
		{time.Date(2026, 3, 11, 15, 30, 0, 0, time.UTC), "2026-03-11"},
		{time.Date(2026, 3, 11, 2, 0, 0, 0, east), "2026-03-10"},
		{time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC), "2026-03-11"},
	} {
		got := core.Day(c.in)
		if !got.Equal(date(c.want)) || got.Location() != time.UTC {
			t.Errorf("Day(%v) = %v, want %s UTC", c.in, got, c.want)
		}
	}
}

func TestCoreAddNormalizesAndNumbers(t *testing.T) {
	s := core.NewStore()
	a, err := s.Add(core.Task{ID: 9, Title: "  Pay rent \t", Due: time.Date(2026, 3, 1, 18, 0, 0, 0, time.UTC),
		Tags: []string{" Home", "money", "home", "Money "}, Done: true, Repeat: "monthly"})
	if err != nil {
		t.Fatal(err)
	}
	if a.ID != 1 || a.Title != "Pay rent" || !a.Due.Equal(date("2026-03-01")) || !slices.Equal(a.Tags, []string{"home", "money"}) ||
		!a.Done || a.Repeat != "monthly" {
		t.Fatalf("Add = %+v", a)
	}
	b, err := s.Add(core.Task{Title: "b"})
	if err != nil || b.ID != 2 || !b.Due.IsZero() || len(b.Tags) != 0 {
		t.Fatalf("second Add = %+v, %v", b, err)
	}
	got, ok := s.Get(1)
	if !ok || got.Title != "Pay rent" || !slices.Equal(got.Tags, []string{"home", "money"}) {
		t.Fatalf("Get(1) = %+v, %v", got, ok)
	}
	if _, ok := s.Get(3); ok {
		t.Fatal("Get(3) found a task")
	}
}

func TestCoreAddRejects(t *testing.T) {
	s := core.NewStore()
	for _, bad := range []core.Task{
		{Title: ""}, {Title: " \t "}, {Title: "x", Tags: []string{""}}, {Title: "x", Tags: []string{"  "}},
		{Title: "x", Tags: []string{"a b"}}, {Title: "x", Tags: []string{"ok", "no_way"}}, {Title: "x", Tags: []string{"é"}},
		{Title: "x", Tags: []string{"*"}},
	} {
		if got, err := s.Add(bad); err == nil {
			t.Errorf("Add(%+v) = %+v, want error", bad, got)
		}
	}
	if len(s.All()) != 0 {
		t.Fatal("a rejected task was stored")
	}
	if a, _ := s.Add(core.Task{Title: "first", Tags: []string{"a-1", "Z9"}}); a.ID != 1 || !slices.Equal(a.Tags, []string{"a-1", "z9"}) {
		t.Fatalf("rejected adds used IDs or tags were not normalized: %+v", a)
	}
}

func TestCoreUpdateAndAll(t *testing.T) {
	s := core.NewStore()
	for _, title := range []string{"a", "b", "c"} {
		if _, err := s.Add(core.Task{Title: title}); err != nil {
			t.Fatal(err)
		}
	}
	if err := s.Update(core.Task{ID: 2, Title: " B ", Tags: []string{"X", "x"}, Due: time.Date(2026, 4, 2, 9, 0, 0, 0, time.UTC), Done: true}); err != nil {
		t.Fatal(err)
	}
	if err := s.Update(core.Task{ID: 4, Title: "d"}); err == nil {
		t.Fatal("Update of a missing ID succeeded")
	}
	if err := s.Update(core.Task{ID: 1, Title: " "}); err == nil {
		t.Fatal("Update with an empty title succeeded")
	}
	all := s.All()
	var titles []string
	for _, task := range all {
		titles = append(titles, task.Title)
	}
	if !slices.Equal(titles, []string{"a", "B", "c"}) || all[1].ID != 2 || !all[1].Done ||
		!all[1].Due.Equal(date("2026-04-02")) || !slices.Equal(all[1].Tags, []string{"x"}) {
		t.Fatalf("All = %+v", all)
	}
}

func TestCoreStoreSharesNoSlices(t *testing.T) {
	s := core.NewStore()
	tags := []string{"a", "b"}
	if _, err := s.Add(core.Task{Title: "x", Tags: tags}); err != nil {
		t.Fatal(err)
	}
	tags[0] = "zzz"
	got, _ := s.Get(1)
	got.Tags[1] = "yyy"
	all := s.All()
	all[0].Tags[0] = "www"
	all[0].Title = "changed"
	if again, _ := s.Get(1); again.Title != "x" || !slices.Equal(again.Tags, []string{"a", "b"}) {
		t.Fatalf("store shares memory with callers: %+v", again)
	}
}

// T2: the dispatch table, ParseArgs, add and done.

func TestParseArgs(t *testing.T) {
	args, err := tasks.ParseArgs([]string{"pay", "--due", "2026-03-01", "the", "--tags", "--x", "rent"})
	if err != nil {
		t.Fatal(err)
	}
	if !slices.Equal(args.Words, []string{"pay", "the", "rent"}) || len(args.Flags) != 2 ||
		args.Flags["due"] != "2026-03-01" || args.Flags["tags"] != "--x" {
		t.Fatalf("ParseArgs = %+v", args)
	}
	args, err = tasks.ParseArgs(nil)
	if err != nil || args.Flags == nil || len(args.Flags) != 0 || len(args.Words) != 0 {
		t.Fatalf("ParseArgs(nil) = %+v, %v", args, err)
	}
	args, err = tasks.ParseArgs([]string{"--tag", ""})
	if v, ok := args.Flags["tag"]; err != nil || !ok || v != "" {
		t.Fatalf("empty value: %+v, %v", args, err)
	}
	for _, bad := range [][]string{{"--due"}, {"a", "--"}, {"--", "x"}, {"--a", "1", "--a", "2"}} {
		if args, err := tasks.ParseArgs(bad); err == nil {
			t.Errorf("ParseArgs(%q) = %+v, want error", bad, args)
		}
	}
}

func env() tasks.Env {
	return tasks.Env{Store: core.NewStore(), Clock: now}
}

func run(t *testing.T, e tasks.Env, line string) string {
	t.Helper()
	out, err := tasks.Run(e, strings.Fields(line))
	if err != nil {
		t.Fatalf("%s: %v", line, err)
	}
	return out
}

func TestRunRejectsUnknownCommandsAndBadArgs(t *testing.T) {
	for _, bad := range [][]string{nil, {}, {"nope"}, {"ADD", "x"}, {"add", "x", "--due"}} {
		if out, err := tasks.Run(env(), bad); err == nil {
			t.Errorf("Run(%q) = %q, want error", bad, out)
		}
	}
}

func TestAdd(t *testing.T) {
	e := env()
	if out := run(t, e, "add Pay the rent --due 2026-03-01 --tags Home,money --every monthly"); out != "added #1\n" {
		t.Fatalf("add printed %q", out)
	}
	if out := run(t, e, "add Call  mum"); out != "added #2\n" {
		t.Fatalf("add printed %q", out)
	}
	all := e.Store.All()
	if len(all) != 2 {
		t.Fatalf("All = %+v", all)
	}
	a, b := all[0], all[1]
	if a.Title != "Pay the rent" || !a.Due.Equal(date("2026-03-01")) || !slices.Equal(a.Tags, []string{"home", "money"}) ||
		a.Repeat != "monthly" || a.Done {
		t.Fatalf("first task = %+v", a)
	}
	if b.Title != "Call mum" || !b.Due.IsZero() || len(b.Tags) != 0 || b.Repeat != "" {
		t.Fatalf("second task = %+v", b)
	}
	for _, bad := range []string{
		"add", "add x --due 2026-02-30", "add x --due 2026-3-01", "add x --tags a,,b",
		"add x --tags bad_tag", "add x --colour red",
	} {
		if out, err := tasks.Run(e, strings.Fields(bad)); err == nil {
			t.Errorf("%s = %q, want error", bad, out)
		}
	}
	if len(e.Store.All()) != 2 {
		t.Fatal("a failed add stored a task")
	}
}

func TestDone(t *testing.T) {
	e := env()
	run(t, e, "add a")
	run(t, e, "add b")
	if out := run(t, e, "done 2"); out != "done #2\n" {
		t.Fatalf("done printed %q", out)
	}
	if got, _ := e.Store.Get(2); !got.Done {
		t.Fatal("task 2 is not done")
	}
	if got, _ := e.Store.Get(1); got.Done {
		t.Fatal("task 1 is done")
	}
	for _, bad := range []string{"done", "done 2", "done 3", "done x", "done 1 2", "done 1 --now yes"} {
		if out, err := tasks.Run(e, strings.Fields(bad)); err == nil {
			t.Errorf("%s = %q, want error", bad, out)
		}
	}
}

// T3: relative due dates.

func TestDueParse(t *testing.T) {
	for _, c := range [][2]string{
		{"today", "2026-03-11"}, {"tomorrow", "2026-03-12"}, {"+0d", "2026-03-11"}, {"+3d", "2026-03-14"},
		{"+21d", "2026-04-01"}, {"+999d", "2028-12-04"}, {"+1w", "2026-03-18"}, {"+02w", "2026-03-25"},
		{"wed", "2026-03-18"}, {"thu", "2026-03-12"}, {"fri", "2026-03-13"}, {"sat", "2026-03-14"},
		{"sun", "2026-03-15"}, {"mon", "2026-03-16"}, {"tue", "2026-03-17"},
		{"2026-02-28", "2026-02-28"}, {"2028-02-29", "2028-02-29"},
	} {
		spec, want := c[0], c[1]
		got, err := due.Parse(spec, now)
		if err != nil || !got.Equal(date(want)) || got.Location() != time.UTC {
			t.Errorf("Parse(%q) = %v, %v; want %s UTC", spec, got, err, want)
		}
	}
}

func TestDueParseUsesTheClocksUTCDate(t *testing.T) {
	late := clock(time.Date(2026, 3, 11, 23, 30, 0, 0, time.FixedZone("west", -5*3600)))
	for _, c := range [][2]string{{"today", "2026-03-12"}, {"+1d", "2026-03-13"}, {"thu", "2026-03-19"}} {
		spec, want := c[0], c[1]
		if got, err := due.Parse(spec, late); err != nil || !got.Equal(date(want)) {
			t.Errorf("Parse(%q) = %v, %v; want %s", spec, got, err, want)
		}
	}
}

func TestDueParseRejects(t *testing.T) {
	for _, spec := range []string{
		"", "Today", " today", "today ", "TOMORROW", "+d", "+1", "+1x", "+-1d", "++1d", "+1000d", "1d", "+1D", "-1d",
		"monday", "Mon", "2026-02-30", "2026-3-01", "26-03-01", "next week", "+ 1d",
	} {
		if got, err := due.Parse(spec, now); err == nil {
			t.Errorf("Parse(%q) = %v, want error", spec, got)
		}
	}
}

// T4: recurrence.

func TestRecurNext(t *testing.T) {
	for _, c := range [][3]string{
		{"daily", "2026-03-11", "2026-03-12"},
		{"every 1 day", "2026-02-28", "2026-03-01"},
		{"every 3 days", "2026-02-27", "2026-03-02"},
		{"every 1 days", "2026-03-11", "2026-03-12"},
		{"weekly", "2026-03-11", "2026-03-18"},
		{"every 2 weeks", "2026-12-24", "2027-01-07"},
		{"every 1 week", "2026-03-11", "2026-03-18"},
		{"monthly", "2026-03-15", "2026-04-15"},
		{"monthly", "2026-01-31", "2026-02-28"},
		{"monthly", "2028-01-31", "2028-02-29"},
		{"monthly", "2026-02-28", "2026-03-28"},
		{"monthly", "2026-12-31", "2027-01-31"},
		{"every 1 month", "2026-05-31", "2026-06-30"},
		{"every 3 months", "2026-11-30", "2027-02-28"},
		{"every 12 months", "2028-02-29", "2029-02-28"},
		{"weekdays", "2026-03-11", "2026-03-12"},
		{"weekdays", "2026-03-13", "2026-03-16"},
		{"weekdays", "2026-03-14", "2026-03-16"},
		{"weekdays", "2026-03-15", "2026-03-16"},
	} {
		rule, err := recur.Parse(c[0])
		if err != nil {
			t.Errorf("Parse(%q): %v", c[0], err)
			continue
		}
		if got := rule.Next(date(c[1])); !got.Equal(date(c[2])) || got.Location() != time.UTC {
			t.Errorf("%q.Next(%s) = %v, want %s UTC", c[0], c[1], got, c[2])
		}
	}
	rule, _ := recur.Parse("daily")
	if got := rule.Next(time.Time(now)); !got.Equal(date("2026-03-12")) {
		t.Errorf("Next from mid-afternoon = %v, want 2026-03-12", got)
	}
}

func TestRecurParseRejects(t *testing.T) {
	for _, text := range []string{
		"", "Daily", "daily ", " weekly", "every", "every 2", "every 0 days", "every -1 days", "every 01 days",
		"every +2 days", "every 2 years", "every  2 days", "every two days", "fortnightly", "every 2 Days", "every 2 days ",
	} {
		if _, err := recur.Parse(text); err == nil {
			t.Errorf("Parse(%q) succeeded, want error", text)
		}
	}
}

func TestRecurAdvance(t *testing.T) {
	task := core.Task{ID: 4, Title: "Pay rent", Due: date("2026-01-31"), Repeat: "monthly", Tags: []string{"home"}, Done: true}
	next, err := recur.Advance(task)
	if err != nil {
		t.Fatal(err)
	}
	if next.ID != 0 || next.Title != "Pay rent" || !next.Due.Equal(date("2026-02-28")) || next.Repeat != "monthly" ||
		!slices.Equal(next.Tags, []string{"home"}) || next.Done {
		t.Fatalf("Advance = %+v", next)
	}
	next.Tags[0] = "changed"
	if task.Tags[0] != "home" {
		t.Fatal("Advance shares Tags with its input")
	}
	for _, bad := range []core.Task{
		{Title: "x", Due: date("2026-03-11")},
		{Title: "x", Due: date("2026-03-11"), Repeat: "sometimes"},
		{Title: "x", Repeat: "daily"},
	} {
		if got, err := recur.Advance(bad); err == nil {
			t.Errorf("Advance(%+v) = %+v, want error", bad, got)
		}
	}
}

// T5: the tag query language.

func TestQueryMatch(t *testing.T) {
	workUrgent := []string{"urgent", "work"}
	for _, c := range []struct {
		tags  []string
		query string
		want  bool
	}{
		{workUrgent, "work", true},
		{workUrgent, "home", false},
		{workUrgent, "work and urgent", true},
		{workUrgent, "work urgent", true},
		{workUrgent, "work home", false},
		{workUrgent, "work and home", false},
		{workUrgent, "work or home", true},
		{workUrgent, "not home", true},
		{workUrgent, "not work", false},
		{workUrgent, "not not work", true},
		{workUrgent, "home or not urgent", false},
		{workUrgent, "not (work or home)", false},
		{workUrgent, "(home or work) and not urgent", false},
		{workUrgent, "work not urgent or home", false},
		{[]string{"home"}, "home or work and urgent", true},
		{[]string{"home"}, "home or work urgent", true},
		{[]string{"home"}, "not home or home", true},
		{[]string{"home"}, "(home)or(work)", true},
		{[]string{"home"}, "\thome\nor  work ", true},
		{[]string{"workshop"}, "work*", true},
		{[]string{"work"}, "work*", true},
		{[]string{"homework"}, "work*", false},
		{[]string{"work"}, "workshop*", false},
		{[]string{"a-1"}, "a-*", true},
		{[]string{"x"}, "*", true},
		{nil, "*", false},
		{nil, "not *", true},
		{nil, "not work", true},
		{nil, "work or not home", true},
	} {
		q, err := query.Parse(c.query)
		if err != nil {
			t.Errorf("Parse(%q): %v", c.query, err)
			continue
		}
		if got := q.Match(core.Task{Title: "x", Tags: c.tags}); got != c.want {
			t.Errorf("Parse(%q).Match(%q) = %v, want %v", c.query, c.tags, got, c.want)
		}
	}
}

func TestQueryParseRejects(t *testing.T) {
	for _, text := range []string{
		"", "   ", "and", "or", "not", "work and", "or work", "work or", "work not", "(work", "work)", "()", "(work))",
		"Work", "work_x", "work**", "w*k", "*work", "a.b", "(work or) home", "not and", "work and or home",
	} {
		if _, err := query.Parse(text); err == nil {
			t.Errorf("Parse(%q) succeeded, want error", text)
		}
	}
}

// T6: CSV export.

func TestExportCSV(t *testing.T) {
	if got := export.CSV(nil); got != "id,title,due,repeat,tags,done\n" {
		t.Errorf("CSV(nil) = %q", got)
	}
	got := export.CSV([]core.Task{
		{ID: 10, Title: "Pay rent", Due: date("2026-03-01"), Repeat: "monthly", Tags: []string{"home", "money"}},
		{ID: 2, Title: `Say "hi", then go`, Done: true},
		{ID: 3, Title: " lead", Tags: []string{"x"}, Repeat: "every 2 weeks"},
		{ID: 4, Title: "two\nlines", Due: date("2027-01-05")},
	})
	want := "id,title,due,repeat,tags,done\n" +
		"10,Pay rent,2026-03-01,monthly,home money,false\n" +
		"2,\"Say \"\"hi\"\", then go\",,,,true\n" +
		"3,\" lead\",,every 2 weeks,x,false\n" +
		"4,\"two\nlines\",2027-01-05,,,false\n"
	if got != want {
		t.Errorf("CSV =\n%s\nwant\n%s", got, want)
	}
}

// T7: list.

// tracker holds tasks around now's date: Wednesday 2026-03-11.
func tracker(t *testing.T) tasks.Env {
	t.Helper()
	e := env()
	for _, task := range []core.Task{
		{Title: "Pay rent", Due: date("2026-03-10"), Tags: []string{"home", "money"}},
		{Title: "Write report", Due: date("2026-03-11"), Tags: []string{"work", "urgent"}},
		{Title: "Call mum", Tags: []string{"home"}},
		{Title: "Book flights", Due: date("2026-03-17"), Tags: []string{"travel"}},
		{Title: "Renew passport", Due: date("2026-03-18"), Tags: []string{"travel", "urgent"}},
		{Title: "File taxes", Due: date("2026-02-01"), Tags: []string{"money"}, Done: true},
		{Title: "Plan sprint", Due: date("2026-03-12"), Tags: []string{"work"}},
		{Title: "Fix bike", Due: date("2026-03-09"), Tags: []string{"home"}, Done: true},
		{Title: "Water plants", Due: date("2026-03-11")},
		{Title: "Read book", Tags: []string{"home"}, Done: true},
	} {
		if _, err := e.Store.Add(task); err != nil {
			t.Fatal(err)
		}
	}
	return e
}

func runWords(t *testing.T, e tasks.Env, words ...string) string {
	t.Helper()
	out, err := tasks.Run(e, words)
	if err != nil {
		t.Fatalf("%q: %v", words, err)
	}
	return out
}

const (
	rent     = "[ ] #1 Pay rent due:2026-03-10 +home +money\n"
	report   = "[ ] #2 Write report due:2026-03-11 +urgent +work\n"
	mum      = "[ ] #3 Call mum +home\n"
	flights  = "[ ] #4 Book flights due:2026-03-17 +travel\n"
	passport = "[ ] #5 Renew passport due:2026-03-18 +travel +urgent\n"
	taxes    = "[x] #6 File taxes due:2026-02-01 +money\n"
	sprint   = "[ ] #7 Plan sprint due:2026-03-12 +work\n"
	bike     = "[x] #8 Fix bike due:2026-03-09 +home\n"
	plants   = "[ ] #9 Water plants due:2026-03-11\n"
	book     = "[x] #10 Read book +home\n"
)

func TestListSelectsAndOrders(t *testing.T) {
	e := tracker(t)
	for _, c := range []struct {
		words []string
		want  string
	}{
		{nil, rent + report + plants + sprint + flights + passport + mum},
		{[]string{"--status", "open"}, rent + report + plants + sprint + flights + passport + mum},
		{[]string{"--status", "done"}, taxes + bike + book},
		{[]string{"--status", "all"}, taxes + bike + rent + report + plants + sprint + flights + passport + mum + book},
		{[]string{"--due", "overdue"}, rent},
		{[]string{"--due", "overdue", "--status", "all"}, taxes + bike + rent},
		{[]string{"--due", "today"}, report + plants},
		{[]string{"--due", "week"}, report + plants + sprint + flights},
		{[]string{"--due", "none"}, mum},
		{[]string{"--due", "none", "--status", "all"}, mum + book},
		{[]string{"--tag", "urgent"}, report + passport},
		{[]string{"--tag", "home or money", "--status", "all"}, taxes + bike + rent + mum + book},
		{[]string{"--tag", "not *"}, plants},
		{[]string{"--tag", "travel", "--due", "week"}, flights},
		{[]string{"--tag", "nothing"}, ""},
		{[]string{"--status", "done", "--due", "today"}, ""},
	} {
		if got := runWords(t, e, append([]string{"list"}, c.words...)...); got != c.want {
			t.Errorf("list %q =\n%s\nwant\n%s", c.words, got, c.want)
		}
	}
}

func TestListRejects(t *testing.T) {
	e := tracker(t)
	for _, words := range [][]string{
		{"list", "--due", "later"}, {"list", "--due", "Today"}, {"list", "--status", "closed"},
		{"list", "--tag", "work and"}, {"list", "extra"}, {"list", "--colour", "red"},
	} {
		if out, err := tasks.Run(e, words); err == nil {
			t.Errorf("%q = %q, want error", words, out)
		}
	}
	if out, err := tasks.Run(env(), []string{"list", "--due", "later"}); err == nil {
		t.Errorf("list --due later on an empty store = %q, want error", out)
	}
}

// T8: report.

func TestReportCountsPerTag(t *testing.T) {
	e := tracker(t)
	want := "home: 2 open, 1 overdue, 2 done\n" +
