// Package tasks runs task-tracker commands against a store.
package tasks

import (
	"errors"
	"fmt"
	"slices"
	"strconv"
	"strings"
	"time"

	"tasks/core"
)

// Env is what a command runs against.
type Env struct {
	Store *core.Store
	Clock core.Clock
}

// Args are a command's arguments: flags written as --name value, and the other words in order.
type Args struct {
	Flags map[string]string
	Words []string
}

// Command runs one command and returns its output.
type Command func(env Env, args Args) (string, error)

// commands is the dispatch table: Run finds a command here by its name.
var commands = map[string]Command{
	"add":    add,
	"done":   done,
	"list":   list,
	"report": report,
}

// ParseArgs splits a command's words into flags and other words.
func ParseArgs(words []string) (Args, error) {
	args := Args{Flags: map[string]string{}}
	for i := 0; i < len(words); i++ {
		name, ok := strings.CutPrefix(words[i], "--")
		if !ok {
			args.Words = append(args.Words, words[i])
			continue
		}
		if name == "" {
			return Args{}, errors.New("tasks: empty flag name")
		}
		if _, seen := args.Flags[name]; seen {
			return Args{}, fmt.Errorf("tasks: repeated flag --%s", name)
		}
		if i+1 == len(words) {
			return Args{}, fmt.Errorf("tasks: flag --%s has no value", name)
		}
		i++
		args.Flags[name] = words[i]
	}
	return args, nil
}

// Run runs the command named by words[0] with the rest of words.
func Run(env Env, words []string) (string, error) {
	if len(words) == 0 {
		return "", errors.New("tasks: no command")
	}
	command, ok := commands[words[0]]
	if !ok {
		return "", fmt.Errorf("tasks: unknown command %q", words[0])
	}
	args, err := ParseArgs(words[1:])
	if err != nil {
		return "", err
	}
	return command(env, args)
}

// only fails when args has a flag not named in names.
func only(args Args, names ...string) error {
	for name := range args.Flags {
		if !slices.Contains(names, name) {
			return fmt.Errorf("tasks: unknown flag --%s", name)
		}
	}
	return nil
}

// add stores a task titled by its words, with optional --due, --tags and --every flags.
func add(env Env, args Args) (string, error) {
	if err := only(args, "due", "tags", "every"); err != nil {
		return "", err
	}
	t := core.Task{Title: strings.Join(args.Words, " "), Repeat: args.Flags["every"]}
	if value, ok := args.Flags["due"]; ok {
		d, err := time.Parse(time.DateOnly, value)
		if err != nil {
			return "", fmt.Errorf("tasks: bad due date %q", value)
		}
		t.Due = d
	}
	if value, ok := args.Flags["tags"]; ok {
		t.Tags = strings.Split(value, ",")
	}
	t, err := env.Store.Add(t)
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("added #%d\n", t.ID), nil
}

// done marks the open task with the given ID done.
func done(env Env, args Args) (string, error) {
	if len(args.Words) != 1 || len(args.Flags) != 0 {
		return "", errors.New("tasks: usage: done ID")
	}
	id, err := strconv.Atoi(args.Words[0])
	t, ok := env.Store.Get(id)
	if err != nil || !ok {
		return "", fmt.Errorf("tasks: no task %q", args.Words[0])
	}
	if t.Done {
		return "", fmt.Errorf("tasks: task #%d is already done", id)
	}
	t.Done = true
	if err := env.Store.Update(t); err != nil {
		return "", err
	}
	return fmt.Sprintf("done #%d\n", id), nil
}

