// Package core holds the task model, the task store and the clock.
package core

import (
	"errors"
	"fmt"
	"slices"
	"strings"
	"time"
)

// Task is one tracked item. Due is a UTC midnight, or the zero time when the task has no due date.
type Task struct {
	ID     int
	Title  string
	Due    time.Time
	Repeat string
	Tags   []string
	Done   bool
}

// Clock supplies the current time.
type Clock interface {
	Now() time.Time
}

// Day returns the UTC midnight that starts t's UTC date.
func Day(t time.Time) time.Time {
	y, m, d := t.UTC().Date()
	return time.Date(y, m, d, 0, 0, 0, 0, time.UTC)
}

// Store holds tasks in memory.
type Store struct {
	tasks []Task
	next  int
}

// NewStore returns an empty store.
func NewStore() *Store {
	return &Store{next: 1}
}

// Add validates t, gives it the next ID and stores it.
func (s *Store) Add(t Task) (Task, error) {
	t, err := normalize(t)
	if err != nil {
		return Task{}, err
	}
	t.ID = s.next
	s.next++
	s.tasks = append(s.tasks, t)
	return clone(t), nil
}

// Get returns the task with id and whether it exists.
func (s *Store) Get(id int) (Task, bool) {
	i := s.index(id)
	if i < 0 {
		return Task{}, false
	}
	return clone(s.tasks[i]), true
}

// Update replaces the stored task that has t's ID.
func (s *Store) Update(t Task) error {
	i := s.index(t.ID)
	if i < 0 {
		return fmt.Errorf("core: no task #%d", t.ID)
	}
	t, err := normalize(t)
	if err != nil {
		return err
	}
	s.tasks[i] = t
	return nil
}

// All returns every stored task in ID order.
func (s *Store) All() []Task {
	out := make([]Task, len(s.tasks))
	for i, t := range s.tasks {
		out[i] = clone(t)
	}
	return out
}

func (s *Store) index(id int) int {
	return slices.IndexFunc(s.tasks, func(t Task) bool { return t.ID == id })
}

// normalize trims the title, moves the due date to its UTC midnight and cleans the tags.
func normalize(t Task) (Task, error) {
	t.Title = strings.TrimSpace(t.Title)
	if t.Title == "" {
		return Task{}, errors.New("core: empty title")
	}
	if !t.Due.IsZero() {
		t.Due = Day(t.Due)
	}
	tags := make([]string, 0, len(t.Tags))
	for _, tag := range t.Tags {
		tag = strings.ToLower(strings.TrimSpace(tag))
		if tag == "" || strings.Trim(tag, "abcdefghijklmnopqrstuvwxyz0123456789-") != "" {
			return Task{}, fmt.Errorf("core: bad tag %q", tag)
		}
		tags = append(tags, tag)
	}
	slices.Sort(tags)
	t.Tags = slices.Compact(tags)
	return t, nil
}

func clone(t Task) Task {
	t.Tags = slices.Clone(t.Tags)
	return t
}

