// Package due reads due dates relative to a clock, and the due-date windows of list filters.
package due

import (
	"fmt"
	"strconv"
	"time"

	"tasks/core"
)

var weekdays = map[string]time.Weekday{
	"sun": time.Sunday, "mon": time.Monday, "tue": time.Tuesday, "wed": time.Wednesday,
	"thu": time.Thursday, "fri": time.Friday, "sat": time.Saturday,
}

// Parse reads a due date written relative to clock's date.
func Parse(spec string, clock core.Clock) (time.Time, error) {
	today := core.Day(clock.Now())
	switch spec {
	case "today":
		return today, nil
	case "tomorrow":
		return today.AddDate(0, 0, 1), nil
	}
	if day, ok := weekdays[spec]; ok {
		return today.AddDate(0, 0, (int(day)-int(today.Weekday())+6)%7+1), nil
	}
	if n, ok := offset(spec); ok {
		return today.AddDate(0, 0, n), nil
	}
	if d, err := time.Parse(time.DateOnly, spec); err == nil {
		return d, nil
	}
	return time.Time{}, fmt.Errorf("due: bad date %q", spec)
}

// offset reads +Nd or +Nw, with one to three digits, as a number of days.
func offset(spec string) (int, bool) {
	if len(spec) < 3 || len(spec) > 5 || spec[0] != '+' {
		return 0, false
	}
	digits := spec[1 : len(spec)-1]
	for _, c := range digits {
		if c < '0' || c > '9' {
			return 0, false
		}
	}
	n, _ := strconv.Atoi(digits)
	switch spec[len(spec)-1] {
	case 'd':
		return n, true
	case 'w':
		return 7 * n, true
	}
	return 0, false
}

// Window returns the range of due dates that filter selects.
func Window(filter string, clock core.Clock) (from, to time.Time, err error) {
	today := core.Day(clock.Now())
	switch filter {
	case "overdue":
		return time.Time{}, today.AddDate(0, 0, -1), nil
	case "today":
		return today, today, nil
	case "week":
		return today, today.AddDate(0, 0, 6), nil
	}
	return time.Time{}, time.Time{}, fmt.Errorf("due: bad filter %q", filter)
}

