package tasks

import (
	"errors"
	"fmt"
	"slices"
	"strings"
	"time"

	"tasks/core"
	"tasks/due"
	"tasks/query"
)

// list prints the tasks its flags select.
func list(env Env, args Args) (string, error) {
	if len(args.Words) > 0 {
		return "", errors.New("tasks: list takes only flags")
	}
	if err := only(args, "status", "tag", "due"); err != nil {
		return "", err
	}
	status, ok := args.Flags["status"]
	if !ok {
		status = "open"
	} else if status != "open" && status != "done" && status != "all" {
		return "", fmt.Errorf("tasks: bad status %q", status)
	}
	filter, filtered := args.Flags["due"]
	if filtered && filter != "none" {
		if _, _, err := due.Window(filter, env.Clock); err != nil {
			return "", err
		}
	}
	tagged, err := matching(env, args.Flags)
	if err != nil {
		return "", err
	}
	var shown []core.Task
	for _, t := range tagged {
		if status == "open" && t.Done || status == "done" && !t.Done {
			continue
		}
		if filtered {
			in := t.Due.IsZero()
			if filter != "none" {
				in, _ = inWindow(t, filter, env.Clock)
			}
			if !in {
				continue
			}
		}
		shown = append(shown, t)
	}
	// Dated tasks first by due date; the stable sort keeps ID order within a date.
	slices.SortStableFunc(shown, func(a, b core.Task) int {
		if a.Due.IsZero() != b.Due.IsZero() {
			if a.Due.IsZero() {
				return 1
			}
			return -1
		}
		return a.Due.Compare(b.Due)
	})
	var out strings.Builder
	for _, t := range shown {
		mark := " "
		if t.Done {
			mark = "x"
		}
		fmt.Fprintf(&out, "[%s] #%d %s", mark, t.ID, t.Title)
		if !t.Due.IsZero() {
			fmt.Fprintf(&out, " due:%s", t.Due.Format(time.DateOnly))
		}
		for _, tag := range t.Tags {
			fmt.Fprintf(&out, " +%s", tag)
		}
		out.WriteString("\n")
	}
	return out.String(), nil
}

// matching returns the stored tasks that the --tag query in flags matches: all of them without one.
func matching(env Env, flags map[string]string) ([]core.Task, error) {
	text, ok := flags["tag"]
	if !ok {
		return env.Store.All(), nil
	}
	q, err := query.Parse(text)
	if err != nil {
		return nil, err
	}
	var out []core.Task
	for _, t := range env.Store.All() {
		if q.Match(t) {
			out = append(out, t)
		}
	}
	return out, nil
}

// inWindow reports whether t's due date is in due.Window(filter, clock).
func inWindow(t core.Task, filter string, clock core.Clock) (bool, error) {
	from, to, err := due.Window(filter, clock)
	return err == nil && !t.Due.IsZero() && !t.Due.Before(from) && !t.Due.After(to), err
}

