// Package query parses and matches tag queries such as "work and not (home or errand*)".
package query

import (
	"fmt"
	"strings"

	"tasks/core"
)

// Query is a parsed tag query.
type Query struct {
	match matcher
}

type matcher func(tags []string) bool

// Parse parses a tag query.
func Parse(text string) (Query, error) {
	p := &parser{tokens: strings.Fields(strings.NewReplacer("(", " ( ", ")", " ) ").Replace(text))}
	m, err := p.or()
	if err != nil {
		return Query{}, err
	}
	if p.peek() != "" {
		return Query{}, fmt.Errorf("query: unexpected %q", p.peek())
	}
	return Query{m}, nil
}

// Match reports whether t's tags satisfy q.
func (q Query) Match(t core.Task) bool {
	return q.match != nil && q.match(t.Tags)
}

type parser struct {
	tokens []string
	pos    int
}

func (p *parser) peek() string {
	if p.pos < len(p.tokens) {
		return p.tokens[p.pos]
	}
	return ""
}

// or reads terms joined by "or".
func (p *parser) or() (matcher, error) {
	left, err := p.and()
	for err == nil && p.peek() == "or" {
		p.pos++
		var right matcher
		if right, err = p.and(); err == nil {
			l := left
			left = func(tags []string) bool { return l(tags) || right(tags) }
		}
	}
	return left, err
}

// and reads factors joined by "and" or by nothing.
func (p *parser) and() (matcher, error) {
	left, err := p.not()
	for err == nil && p.peek() != "" && p.peek() != "or" && p.peek() != ")" {
		if p.peek() == "and" {
			p.pos++
		}
		var right matcher
		if right, err = p.not(); err == nil {
			l := left
			left = func(tags []string) bool { return l(tags) && right(tags) }
		}
	}
	return left, err
}

// not reads "not" factor, a parenthesized query, or a tag pattern.
func (p *parser) not() (matcher, error) {
	token := p.peek()
	p.pos++
	switch token {
	case "not":
		m, err := p.not()
		return func(tags []string) bool { return !m(tags) }, err
	case "(":
		m, err := p.or()
		if err == nil && p.peek() != ")" {
			err = fmt.Errorf("query: missing )")
		}
		p.pos++
		return m, err
	case "", ")", "and", "or":
		return nil, fmt.Errorf("query: expected a tag, got %q", token)
	}
	prefix, wild := strings.CutSuffix(token, "*")
	if strings.Trim(prefix, "abcdefghijklmnopqrstuvwxyz0123456789-") != "" || prefix == "" && !wild {
		return nil, fmt.Errorf("query: bad tag %q", token)
	}
	return func(tags []string) bool {
		for _, tag := range tags {
			if tag == prefix || wild && strings.HasPrefix(tag, prefix) {
				return true
			}
		}
		return false
	}, nil
}

