// Package recur reads recurrence rules and advances recurring tasks.
package recur

import (
	"errors"
	"fmt"
	"slices"
	"strconv"
	"strings"
	"time"

	"tasks/core"
)

// Rule is a parsed recurrence rule.
type Rule struct {
	n    int
	unit string // "day", "week", "month" or "weekday"
}

// Parse reads a recurrence rule such as "weekly" or "every 3 days".
func Parse(text string) (Rule, error) {
	switch text {
	case "daily":
		return Rule{1, "day"}, nil
	case "weekly":
		return Rule{1, "week"}, nil
	case "monthly":
		return Rule{1, "month"}, nil
	case "weekdays":
		return Rule{1, "weekday"}, nil
	}
	words := strings.Split(text, " ")
	if len(words) == 3 && words[0] == "every" {
		n, err := strconv.Atoi(words[1])
		unit := strings.TrimSuffix(words[2], "s")
		if err == nil && n >= 1 && strconv.Itoa(n) == words[1] && (unit == "day" || unit == "week" || unit == "month") {
			return Rule{n, unit}, nil
		}
	}
	return Rule{}, fmt.Errorf("recur: bad rule %q", text)
}

// Next returns the first occurrence after date.
func (r Rule) Next(date time.Time) time.Time {
	date = core.Day(date)
	switch r.unit {
	case "day":
		return date.AddDate(0, 0, r.n)
	case "week":
		return date.AddDate(0, 0, 7*r.n)
	case "month":
		y, m, d := date.Date()
		first := time.Date(y, m+time.Month(r.n), 1, 0, 0, 0, 0, time.UTC)
		last := first.AddDate(0, 1, -1).Day()
		return first.AddDate(0, 0, min(d, last)-1)
	}
	next := date.AddDate(0, 0, 1)
	for next.Weekday() == time.Saturday || next.Weekday() == time.Sunday {
		next = next.AddDate(0, 0, 1)
	}
	return next
}

// Advance returns the next occurrence of the recurring task t.
func Advance(t core.Task) (core.Task, error) {
	rule, err := Parse(t.Repeat)
	if err != nil {
		return core.Task{}, err
	}
	if t.Due.IsZero() {
		return core.Task{}, errors.New("recur: a recurring task needs a due date")
	}
	t.ID, t.Done, t.Due = 0, false, rule.Next(t.Due)
	t.Tags = slices.Clone(t.Tags)
	return t, nil
}

