package tasks

import (
	"errors"
	"fmt"
	"maps"
	"slices"
	"strings"
)

// counts are one report line's numbers.
type counts struct{ open, overdue, done int }

// report prints tag statistics.
func report(env Env, args Args) (string, error) {
	if len(args.Words) > 0 {
		return "", errors.New("tasks: report takes only flags")
	}
	if err := only(args, "tag"); err != nil {
		return "", err
	}
	tagged, err := matching(env, args.Flags)
	if err != nil {
		return "", err
	}
	var total counts
	byTag := map[string]*counts{}
	for _, t := range tagged {
		overdue, err := inWindow(t, "overdue", env.Clock)
		if err != nil {
			return "", err
		}
		lines := []*counts{&total}
		for _, tag := range t.Tags {
			if byTag[tag] == nil {
				byTag[tag] = &counts{}
			}
			lines = append(lines, byTag[tag])
		}
		for _, c := range lines {
			switch {
			case t.Done:
				c.done++
			case overdue:
				c.open++
				c.overdue++
			default:
				c.open++
			}
		}
	}
	var out strings.Builder
	for _, tag := range slices.Sorted(maps.Keys(byTag)) {
		c := byTag[tag]
		fmt.Fprintf(&out, "%s: %d open, %d overdue, %d done\n", tag, c.open, c.overdue, c.done)
	}
	fmt.Fprintf(&out, "TOTAL: %d open, %d overdue, %d done\n", total.open, total.overdue, total.done)
	return out.String(), nil
}
